advanced_data = {
    "historical-aquincum-museum-extra": ("Das Aquincum Museum in Budapest bietet einen faszinierenden Einblick in das Leben der römischen Provinz Pannonia. Auf dem weitläufigen Ausgrabungsgelände können Besucher die Überreste der einstigen Hauptstadt besichtigen, die im 1. Jahrhundert n. Chr. gegründet wurde. Zu sehen sind Fundamente von Wohngebäuden, öffentlichen Bädern, Märkten und Heiligtümern. Besonders beeindruckend sind die gut erhaltenen Mosaikböden und die rekonstruierten Wandmalereien, die den Luxus der damaligen Zeit widerspiegeln. Das dazugehörige Museumsgebäude beherbergt wertvolle archäologische Funde, darunter die berühmte Aquincum-Orgel, eine antike Wasserorgel aus dem 3. Jahrhundert. Die Anlage vermittelt anschaulich, wie die Römer an der Grenze des Imperiums lebten, arbeiteten und ihre Freizeit gestalteten. Ein Spaziergang durch die Ruinenstadt fühlt sich an wie eine Zeitreise in die Antike, bei der die Geschichte lebendig wird.", ["Aquincum war die Hauptstadt der römischen Provinz Pannonia Inferior.", "Die Stadt hatte in ihrer Blütezeit schätzungsweise 30.000 bis 40.000 Einwohner.", "Das Gelände beherbergt zwei Amphitheater, eines für das Militär und eines für Zivilisten.", "Die 1931 gefundene Aquincum-Orgel ist eines der bedeutendsten antiken Musikinstrumente weltweit.", "Viele Gebäude waren mit einer fortschrittlichen Fußbodenheizung, dem Hypokaustum, ausgestattet.", "Das Museum wurde bereits 1894 offiziell eröffnet.", "Es gibt ein spezielles 'Malerhaus', das die römische Innendekoration rekonstruiert.", "Regelmäßig finden historische Festivals wie die Floralia statt, um die römische Kultur zu feiern."]),
    "historical-vasarcsarnok-extra": ("Die Große Markthalle in Budapest, auch als Zentrale Markthalle bekannt, ist nicht nur ein Ort für den täglichen Einkauf, sondern ein architektonisches Meisterwerk des späten 19. Jahrhunderts. Das vom Architekten Samu Pecz entworfene Gebäude beeindruckt durch seine gewaltige Stahlkonstruktion und das farbenfrohe Dach aus Zsolnay-Ziegeln. Auf drei Etagen bietet die Halle eine unglaubliche Vielfalt an ungarischen Spezialitäten, von frischem Obst und Gemüse bis hin zu Fleischwaren wie der berühmten Salami und Paprikapulver. Im Obergeschoss finden Besucher traditionelles Kunsthandwerk und Imbissstände, die lokale Gerichte wie Lángos anbieten. Die Markthalle ist ein lebendiger Treffpunkt für Einheimische und Touristen gleichermaßen und spiegelt die kulinarische Kultur Ungarns wider. Ihre Lage direkt am Fővám tér, in der Nähe der Freiheitsbrücke, macht sie zu einem unverzichtbaren Ziel bei jedem Besuch in der ungarischen Hauptstadt.", ["Die Markthalle wurde 1897 eröffnet und war damals eine der modernsten ihrer Art.", "Das Dach ist mit bunt glasierter Keramik aus der berühmten Zsolnay-Manufaktur gedeckt.", "Das Gebäude hat eine Gesamtfläche von etwa 10.000 Quadratmetern.", "Im Keller befanden sich ursprünglich Fischbecken und Kühllager.", "Die Halle verfügt über einen eigenen Gleisanschluss, der früher direkt zur Donau führte.", "Samu Pecz gewann den Wettbewerb für den Bau gegen mehrere internationale Architekten.", "Während des Zweiten Weltkriegs wurde das Gebäude schwer beschädigt und in den 1990ern umfassend renoviert.", "Die Markthalle wurde 1999 mit dem FIABCI Prix d’Excellence für ihre Architektur ausgezeichnet."]),
    "historical-operahaz-extra": ("Die Ungarische Staatsoper in Budapest gilt als eines der prachtvollsten Gebäude der Neorenaissance in Europa. Entworfen vom berühmten Architekten Miklós Ybl und im Jahr 1884 eingeweiht, war sie ein Geschenk von Kaiser Franz Joseph I. an die Stadt. Die Fassade ist mit Statuen berühmter Komponisten wie Ferenc Liszt und Ferenc Erkel geschmückt. Das Innere der Oper ist überwältigend: Marmorsäulen, goldverzierte Decken und prächtige Fresken von namhaften ungarischen Künstlern wie Károly Lotz prägen das Bild. Besonders bekannt ist die Oper für ihre exzellente Akustik, die weltweit zu den besten gehört. Ein Besuch einer Vorstellung oder eine Führung durch das Gebäude ermöglicht es, den Glanz der österreichisch-ungarischen Monarchie hautnah zu erleben. Die Oper ist nicht nur ein kulturelles Zentrum für Musik und Ballett, sondern auch ein nationales Symbol für die ungarische Kunstfertigkeit.", ["Die Oper wurde am 27. September 1884 nach neunjähriger Bauzeit eröffnet.", "Kaiser Franz Joseph I. finanzierte den Bau unter der Bedingung, dass sie nicht größer als die Wiener Oper wird.", "Der hufeisenförmige Zuschauerraum bietet Platz für etwa 1.200 Gäste.", "Das Deckenfresko im Zuschauerraum zeigt den Olymp und die griechischen Götter.", "Der massive Kronleuchter im Hauptsaal wiegt über zwei Tonnen.", "Gustav Mahler war von 1888 bis 1891 Direktor der Oper.", "Die Akustik wird oft als die drittbeste in Europa nach der Mailänder Scala und der Pariser Oper bezeichnet.", "Nach einer umfassenden Renovierung wurde die Oper im Jahr 2022 feierlich wiedereröffnet."]),
    "animal-habitat-allatkert-bp-extra": ("Der Budapester Zoo und Botanische Garten ist eine der ältesten und traditionsreichsten zoologischen Einrichtungen der Welt. Er wurde 1866 eröffnet und liegt im Herzen des Stadtwäldchens. Was diesen Zoo so besonders macht, ist die einzigartige Kombination aus vielfältiger Tierwelt und außergewöhnlicher Architektur. Viele der Tierhäuser sind im Jugendstil oder mit orientalischen Elementen gestaltet, wie das berühmte Elefantenhaus mit seinem Zsolnay-Keramikdach. Der Zoo beherbergt über 1.000 Tierarten aus allen Kontinenten, eingebettet in eine botanisch wertvolle Parklandschaft. Neben der Erhaltung seltener Arten legt der Zoo großen Wert auf Bildung und Forschung. Besonders für Familien ist er ein beliebtes Ausflugsziel, da er moderne Tierhaltung mit historischem Charme verbindet. Ein Highlight ist das 'Holnemvolt-Schloss', ein Bereich, der sich speziell an Kinder richtet und traditionelle ungarische Haustierrassen sowie spielerische Lernstationen bietet.", ["Der Zoo wurde am 9. August 1866 als erster Tiergarten Ungarns eröffnet.", "Das Elefantenhaus ist ein Meisterwerk des ungarischen Jugendstils von Kornél Neuschloß.", "Der künstliche 'Große Fels' wurde zu Beginn des 20. Jahrhunderts aus Beton erbaut.", "In den 1910er Jahren galt der Zoo als einer der modernsten und schönsten weltweit.", "Die Anlage beherbergt auch ein bedeutendes Palmenhaus und ein Aquarium.", "Sissi, die Kaiserin Elisabeth, schenkte dem Zoo bei der Eröffnung eine Giraffe.", "Der Zoo ist auch ein Rettungszentrum für verletzte einheimische Wildtiere.", "Das gesamte Areal steht aufgrund seiner historischen Gebäude unter Denkmalschutz."]),
    "port-csepel-kikoto-extra": ("Der Freihafen von Csepel ist der bedeutendste Binnenhafen Ungarns und ein zentraler Knotenpunkt für den internationalen Güterverkehr auf der Donau. Gelegen am nördlichen Ende der Insel Csepel in Budapest, dient er als Tor für Warenströme zwischen West- und Osteuropa. Der Hafen wurde in den 1920er Jahren konzipiert, um die wirtschaftliche Bedeutung Ungarns als Logistikzentrum zu stärken. Er verfügt über moderne Containerterminals, Getreidesilos und spezialisierte Lagerhäuser. Durch die Anbindung an das Schienen- und Straßennetz ermöglicht der Hafen einen effizienten intermodalen Transport. Trotz der industriellen Nutzung ist der Hafen auch ein Symbol für die maritime Tradition Ungarns, obwohl das Land keinen direkten Zugang zum Meer hat. Die ständige Modernisierung sorgt dafür, dass Csepel wettbewerbsfähig bleibt und eine Schlüsselrolle in der europäischen Logistikkette spielt. Für die Wirtschaft der Region ist er ein unverzichtbarer Motor für Handel und Beschäftigung.", ["Der Hafen wurde offiziell im Jahr 1928 durch den Reichsverweser Miklós Horthy eingeweiht.", "Er liegt am Donaukilometer 1640 und ist ganzjährig schiffbar.", "Die Insel Csepel ist die größte Insel in der ungarischen Donau.", "Der Hafen verfügt über einen eigenen Freihafenstatus, was Zollvorteile bietet.", "Die Getreidesilos des Hafens gehören zu den größten Kapazitäten in der Region.", "Es gibt direkte Schienenverbindungen zu den wichtigsten europäischen Industriezentren.", "Der Hafen spielt eine wichtige Rolle im Rahmen des Transeuropäischen Verkehrsnetzes (TEN-V).", "Jährlich werden hier Millionen Tonnen an Gütern, insbesondere Erze, Kohle und Getreide, umgeschlagen."]),
    "historical-siklosi-var-extra": ("Die Burg Siklós im Süden Ungarns ist eine der am besten erhaltenen mittelalterlichen Festungen des Landes. Ihre Geschichte reicht bis in das 13. Jahrhundert zurück, und im Gegensatz zu vielen anderen Burgen wurde sie über die Jahrhunderte hinweg kontinuierlich bewohnt und ausgebaut. Die Architektur der Burg zeigt eine harmonische Mischung aus Gotik, Renaissance und Barock, was auf die verschiedenen Adelsfamilien wie die Garai oder Batthyány zurückzuführen ist, die hier residierten. Besonders sehenswert ist die Schlosskapelle mit ihren feinen gotischen Fenstern und Fresken. Heute beherbergt die Burg ein Museum, das die Geschichte der Festung, das Leben des Adels und mittelalterliche Waffen präsentiert. Die dicken Mauern und die imposante Lage auf einem Hügel bieten zudem einen weiten Ausblick über die umliegende Weinregion Villány. Ein Besuch in Siklós verbindet historische Entdeckungen mit der malerischen Schönheit des ungarischen Südens.", ["Die erste schriftliche Erwähnung der Burg stammt aus dem Jahr 1294.", "Im Jahr 1401 wurde König Sigismund von Luxemburg zeitweise in der Burg gefangen gehalten.", "Die Burgkapelle gilt als eines der schönsten Beispiele spätgotischer Architektur in Ungarn.", "Das Burgmuseum zeigt unter anderem eine Ausstellung über die berühmte ungarische Serie 'Der Kapitän vom Tenkesberg'.", "In der Burg gibt es ein funktionstüchtiges mittelalterliches Gefängnis und eine Folterkammer.", "Die Familie Batthyány baute die Burg im 18. Jahrhundert zu einem prachtvollen Schloss um.", "Siklós liegt in unmittelbarer Nähe zur berühmten Weinregion Villány.", "Die Burg dient regelmäßig als Kulisse für historische Festivals und Ritterspiele."]),
    "historical-mohacsi-emlekhely-extra": ("Die Nationale Gedenkstätte von Mohács erinnert an eines der tragischsten Ereignisse der ungarischen Geschichte: die Schlacht gegen das Osmanische Reich im Jahr 1526. An diesem Ort erlitt das ungarische Heer eine vernichtende Niederlage, bei der auch König Ludwig II. ums Leben kam, was das Ende der ungarischen Unabhängigkeit für 150 Jahre einläutete. Der Gedenkpark wurde 1976, zum 450. Jahrestag der Schlacht, eröffnet. Das beeindruckende kreisförmige Areal beherbergt zahlreiche kunstvoll geschnitzte Holzstatuen, die symbolisch für die gefallenen Krieger und den Untergang des mittelalterlichen Ungarns stehen. Ein modernes Ausstellungsgebäude informiert Besucher über die Hintergründe, den Verlauf und die Folgen der Schlacht durch interaktive Displays und archäologische Funde. Die stille, fast andächtige Atmosphäre des Parks macht ihn zu einem Ort der Besinnung und des Gedenkens an die nationale Identität und die Opfer der Vergangenheit.", ["Die Schlacht von Mohács fand am 29. August 1526 statt.", "Der Gedenkpark wurde an der Stelle errichtet, an der Massengräber der Gefallenen entdeckt wurden.", "Die über 1.700 Holzstatuen wurden von namhaften ungarischen Künstlern geschaffen.", "Das Eingangsgebäude ist so gestaltet, dass es an eine ungarische Krone erinnert.", "In der Ausstellung sind originale Waffen und Rüstungsteile aus dem 16. Jahrhundert zu sehen.", "Die Gedenkstätte erstreckt sich über eine Fläche von etwa sieben Hektar.", "Ein Glockenturm im Park läutet regelmäßig zum Gedenken an die Toten.", "Mohács ist heute auch für den Busójárás bekannt, ein Maskenfest, das zum UNESCO-Weltkulturerbe gehört."]),
    "historical-pecsi-szekesegyhaz-extra": ("Die Kathedrale von Pécs, offiziell Basilika St. Peter und Paul, ist das markanteste Wahrzeichen der Stadt im Süden Ungarns. Mit ihren vier charakteristischen Türmen dominiert sie den Domplatz und erzählt eine fast tausendjährige Geschichte. Die Ursprünge der Kirche liegen in der frühchristlichen Zeit, während der heutige Bau eine faszinierende Mischung aus romanischen Grundelementen und einer historisierenden Erneuerung des 19. Jahrhunderts darstellt. Im Inneren beeindruckt die Kathedrale durch eine überwältigende künstlerische Gestaltung: Die Wände sind vollständig mit prächtigen Fresken bedeckt, die biblische Szenen und die Geschichte der ungarischen Heiligen darstellen. Besonders die Unterkirche mit ihren massiven Pfeilern vermittelt eine mystische Atmosphäre. Als Sitz des Bistums Pécs ist die Kathedrale nicht nur ein religiöses Zentrum, sondern auch ein bedeutendes Denkmal der europäischen Architekturgeschichte, eingebettet in das kulturelle Erbe einer Stadt, die einst römisch, christlich und osmanisch geprägt war.", ["Die Kathedrale steht über den Ruinen einer frühchristlichen Grabkapelle aus dem 4. Jahrhundert.", "König Stephan der Heilige gründete das Bistum Pécs im Jahr 1009.", "Während der osmanischen Herrschaft wurde die Kirche als Moschee und Vorratslager genutzt.", "Die heutige neoromanische Form erhielt der Dom bei einem Umbau zwischen 1882 und 1891.", "Die vier Türme sind jeweils 60 Meter hoch.", "Im Inneren befinden sich bedeutende Werke der Maler Bertalan Székely und Károly Lotz.", "Papst Johannes Paul II. erhob die Kirche 1991 in den Rang einer Basilica minor.", "Die Akustik der Kathedrale ist hervorragend und wird oft für Orgelkonzerte genutzt."]),
    "animal-habitat-pecsi-allatkert-extra": ("Der Zoo von Pécs liegt malerisch an den Hängen des Mecsek-Gebirges und bietet Besuchern eine einzigartige Kombination aus Tiererlebnissen und Naturpanorama. Gegründet im Jahr 1960, wurde die Anlage in den letzten Jahren umfassend modernisiert und erweitert. Ein besonderes Highlight ist das große Aquarium und Terrarium, das im Hauptgebäude untergebracht ist und eine Vielzahl von Meeresbewohnern, Reptilien und Amphibien zeigt. Die Gehege für größere Tiere wie Löwen, Zebras und Braunbären sind modern und naturnah gestaltet. Durch seine terrassenförmige Anlage bietet der Zoo immer wieder spektakuläre Ausblicke auf die Stadt Pécs. Neben der Präsentation exotischer Arten widmet sich der Zoo auch dem Schutz einheimischer Tiere. Für Familien gibt es Streichelzoos und thematische Spielplätze, die den Besuch zu einem lehrreichen Vergnügen machen. Der Zoo ist ein fester Bestandteil des touristischen Angebots der Kulturhauptstadt von 2010.", ["Der Zoo wurde ursprünglich in nur 100 Tagen von freiwilligen Bürgern der Stadt erbaut.", "Er beherbergt heute über 1.000 Tiere aus rund 250 verschiedenen Arten.", "Das Aquarium verfügt über ein 100.000 Liter fassendes Becken für Haie.", "Der Zoo liegt auf einer Höhe von etwa 300 Metern über dem Meeresspiegel.", "Es gibt ein spezielles Gebäude für Schimpansen mit großzügigen Klettermöglichkeiten.", "Zu den seltenen Arten im Zoo gehören der Rote Panda und das Zwergflusspferd.", "Der Zoo ist Mitglied im Europäischen Verband der Zoos und Aquarien (EAZA).", "Im Rahmen von Umweltbildungsprogrammen werden regelmäßig Nachtführungen angeboten."]),
    "industry-beremendi-cementgyar-extra": ("Das Zementwerk Beremend im äußersten Süden Ungarns ist einer der wichtigsten Industriestandorte des Landes und ein bedeutender Produzent für die Bauwirtschaft in Mitteleuropa. Die Fabrik nutzt die gewaltigen Kalksteinvorkommen der Region, um hochwertigen Zement für verschiedenste Infrastrukturprojekte herzustellen. Seit ihrer Gründung wurde die Anlage stetig modernisiert und gehört heute zu den umweltfreundlichsten und effizientesten Zementwerken der Region. Das Werk ist ein entscheidender Wirtschaftsfaktor für das Komitat Baranya und sichert zahlreiche Arbeitsplätze. Neben der Produktion legt das Unternehmen großen Wert auf Nachhaltigkeit und die Rekultivierung der Kalksteinbrüche. Die markanten Silos und Industrieanlagen prägen das Landschaftsbild nahe der kroatischen Grenze. Beremend steht beispielhaft für die Transformation der ungarischen Schwerindustrie hin zu modernen, technologiegetriebenen Produktionsstandards, die auch internationalen Anforderungen an den Klimaschutz gerecht werden wollen.", ["Die erste Zementproduktion in Beremend begann bereits im Jahr 1911.", "Das Werk gehört heute zur Duna-Dráva Cement Kft., einem Teil der Heidelberg Materials Gruppe.", "Die Kalksteinbrüche bei Beremend zählen zu den größten ihrer Art in Ungarn.", "Das Werk setzt modernste Filtertechnologien ein, um die Staubemissionen minimal zu halten.", "Ein Teil der benötigten Energie wird durch die Verbrennung von Ersatzbrennstoffen gewonnen.", "Der hier produzierte Zement wurde beim Bau zahlreicher ungarischer Autobahnen verwendet.", "Beremend ist die südlichste Gemeinde Ungarns.", "Das Unternehmen engagiert sich stark in sozialen Projekten der umliegenden Dörfer."]),
    "historical-kalocsai-szekesegyhaz-extra": ("Die Kathedrale von Kalocsa, auch als Erzbischöfliche Kathedrale Mariä Himmelfahrt bekannt, ist ein Juwel der Barockarchitektur in der ungarischen Tiefebene. Kalocsa ist eines der ältesten Bistümer Ungarns, gegründet von König Stephan dem Heiligen. Die heutige Kirche wurde im 18. Jahrhundert an der Stelle ihrer zerstörten Vorgängerbauten errichtet. Die prachtvolle rosa-weiße Fassade mit ihren zwei Türmen ist weithin sichtbar. Im Inneren erwartet den Besucher eine opulente Ausstattung mit goldenen Ornamenten, beeindruckenden Deckenmalereien und einer der bedeutendsten Orgeln des Landes. Direkt neben der Kathedrale befindet sich das Erzbischöfliche Palais, das eine wertvolle Bibliothek und das Diözesanmuseum beherbergt. Die Kathedrale ist nicht nur ein spirituelles Zentrum, sondern auch ein Ort von großer kulturhistorischer Bedeutung, der die tiefe religiöse Tradition und die künstlerische Blütezeit des ungarischen Barocks repräsentiert.", ["Das Erzbistum Kalocsa wurde bereits im Jahr 1001 gegründet.", "Die heutige Kirche wurde zwischen 1735 und 1754 nach Plänen von Andreas Mayerhoffer erbaut.", "Die Orgel der Kathedrale wurde von der berühmten Firma Angster aus Pécs gefertigt.", "In der Krypta ruhen viele der ehemaligen Erzbischöfe von Kalocsa.", "Die Deckenfresken stammen von dem Wiener Maler Ludwig von Langenmantel.", "Die Bibliothek des Erzbistums enthält über 150.000 Bände, darunter seltene Inkunabeln.", "Kalocsa ist weltweit auch für seine Paprikaproduktion und traditionelle Stickerei bekannt.", "Franz Liszt besuchte die Kathedrale mehrfach und spielte auf der dortigen Orgel."]),
    "historical-kecskemeti-varoshaza-extra": ("Das Rathaus von Kecskemét ist ein herausragendes Beispiel für den ungarischen Sezessionsstil und eines der schönsten Regierungsgebäude des Landes. Es wurde zwischen 1893 und 1897 nach Entwürfen der Architekten Ödön Lechner und Gyula Pártos errichtet. Die Fassade ist reich mit farbenfroher Zsolnay-Keramik und ungarischen Volksmotiven verziert, was dem Gebäude ein fast märchenhaftes Aussehen verleiht. Besonders berühmt ist der Festsaal mit seinen monumentalen Wandgemälden von Bertalan Székely, die wichtige Momente der ungarischen Geschichte darstellen. Ein tägliches Highlight für Besucher ist das Glockenspiel über dem Haupteingang, das zu jeder vollen Stunde klassische und volkstümliche Melodien spielt. Das Rathaus ist das Herzstück des architektonischen Ensembles im Zentrum von Kecskemét und symbolisiert den bürgerlichen Stolz und die kulturelle Eigenständigkeit der Stadt zur Zeit der Jahrhundertwende.", ["Das Rathaus wurde zum Gedenken an das 1.000-jährige Bestehen Ungarns erbaut.", "Ödön Lechner wird oft als der 'ungarische Gaudí' bezeichnet.", "Das Glockenspiel besteht aus 37 kleinen Glocken und spielt Melodien von Kodály und Erkel.", "Der Festsaal ist ein beliebter Ort für Hochzeiten und offizielle Empfänge.", "In den 1990er Jahren wurde die Keramikfassade aufwendig restauriert.", "Das Gebäude überstand das schwere Erdbeben von 1911 fast unbeschadet.", "Das Dach zeigt komplexe geometrische Muster aus farbig glasierten Ziegeln.", "Kecskemét ist die Geburtsstadt des Komponisten Zoltán Kodály, dessen Erbe in der Stadt allgegenwärtig ist."]),
    "historical-kecskemeti-nagytemplom-extra": ("Die Große Kirche von Kecskemét, gewidmet dem heiligen Nikolaus, ist die größte spätbarocke Kirche in der ungarischen Tiefebene (Alföld). Ihr massiver Turm, der 73 Meter in die Höhe ragt, ist ein weithin sichtbares Orientierungsmerkmal der Stadt. Der Bau der Kirche dauerte mehrere Jahrzehnte im 18. Jahrhundert und wurde von Gáspár Oswald geleitet. Das Äußere wirkt eher streng und klassizistisch, während das Innere durch seine Weite und die kunstvolle barocke Ausstattung beeindruckt. Die Altargemälde und die prunkvolle Kanzel sind Zeugnisse hoher handwerklicher Qualität. Die Kirche spielt eine zentrale Rolle im religiösen Leben von Kecskemét und ist Teil des beeindruckenden Ensembles von Sakralbauten am Hauptplatz der Stadt, zu dem auch reformierte und lutherische Kirchen gehören. Ihre Geschichte ist eng mit dem Aufstieg Kecskeméts als Handelszentrum für Landwirtschaft und Viehzucht verbunden.", ["Der Bau begann im Jahr 1774 und wurde erst 1806 vollständig abgeschlossen.", "Mit einer Länge von 62 Metern und einer Breite von 25 Metern ist sie ein monumentales Bauwerk.", "Der Turm wurde nach einem Brand im Jahr 1819 in seiner heutigen Form wiederaufgebaut.", "In den Nischen der Fassade stehen Statuen der Apostel Petrus und Paulus.", "Die Orgel der Kirche ist für ihren vollen Klang bekannt und wird regelmäßig bei Konzerten genutzt.", "Die Kirche überstand das verheerende Erdbeben von 1911 mit nur geringen Schäden.", "An der Außenwand befinden sich Gedenktafeln für die Opfer der Weltkriege.", "Vom Turm aus bietet sich bei klarem Wetter ein herrlicher Blick über die gesamte Puszta-Region."]),
    "animal-habitat-kecskemeti-vadaskert-extra": ("Der Kecskeméter Wildpark (Kecskeméti Vadaskert) ist ein charmanter Zoo, der sich besonders durch seine familiäre Atmosphäre und seinen Fokus auf Bildung auszeichnet. Er ist flächenmäßig der kleinste staatliche Zoo Ungarns, bietet aber dennoch eine überraschende Vielfalt an Tierarten aus aller Welt. Neben exotischen Tieren wie Tigern, Löwen und Affen legt der Park einen besonderen Schwerpunkt auf die Präsentation der heimischen ungarischen Fauna sowie auf traditionelle ungarische Nutztierrassen. Der Zoo engagiert sich stark im Naturschutz und dient als Auffangstation für verletzte Wildtiere aus der Region. Die Wege sind schattig und führen durch einen gepflegten Baumbestand, was den Besuch auch an heißen Sommertagen angenehm macht. Besonders für Kinder gibt es viele interaktive Möglichkeiten, Tiere aus nächster Nähe zu erleben und spielerisch etwas über die Natur zu lernen. Der Park ist ein grünes Juwel am Rande der Stadt.", ["Der Wildpark wurde im Jahr 1971 eröffnet.", "Er beherbergt etwa 500 Tiere aus rund 120 verschiedenen Arten.", "Besonders stolz ist der Zoo auf seine Zuchterfolge bei seltenen Affenarten.", "Es gibt ein spezielles Gehege für die ungarischen Steppenrinder und Zackelschafe.", "Der Park organisiert regelmäßig Zoopädagogik-Stunden für Schulklassen.", "In den letzten Jahren wurden viele Gehege nach modernsten Standards für das Tierwohl umgebaut.", "Der Kecskeméter Zoo ist bekannt für seine erfolgreiche Aufzucht von Raubvögeln.", "Jeden Samstag gibt es öffentliche Schaufütterungen, bei denen Pfleger Wissenswertes berichten."]),
    "industry-mercedes-kecskemet-extra": ("Das Mercedes-Benz Werk in Kecskemét ist eine der modernsten Automobilproduktionsstätten in Europa und ein Eckpfeiler der ungarischen Wirtschaft. Seit seiner Eröffnung im Jahr 2012 werden hier Premium-Kompaktwagen wie die A-Klasse und der CLA für den Weltmarkt gefertigt. Das Werk zeichnet sich durch hochautomatisierte Prozesse, modernste Robotertechnik und strenge Qualitätsstandards aus. Es war die erste Mercedes-Benz Pkw-Fabrik in Osteuropa und hat die Region Kecskemét nachhaltig verändert, indem es Tausende von hochqualifizierten Arbeitsplätzen schuf und zahlreiche Zulieferbetriebe anzog. Mercedes-Benz setzt in Kecskemét verstärkt auf Nachhaltigkeit, mit dem Ziel, die Produktion CO2-neutral zu gestalten. Das Werk ist zudem ein Vorreiter in der dualen Ausbildung in Ungarn, wobei es eng mit lokalen Schulen und Universitäten kooperiert, um Nachwuchskräfte praxisnah auszubilden.", ["Die Entscheidung für den Standort Kecskemét fiel im Jahr 2008.", "Das Werk wurde in einer Rekordzeit von weniger als vier Jahren errichtet.", "Hier wird exklusiv das CLA Coupé und der CLA Shooting Brake für den gesamten Weltmarkt produziert.", "Das Areal umfasst eine Fläche von über 440 Hektar.", "Das Werk verfügt über ein eigenes Presswerk, einen Karosserierohbau, eine Lackiererei und die Endmontage.", "Über 4.000 Mitarbeiter sind direkt im Werk beschäftigt.", "Das Werk wurde bereits mehrfach für seine Energieeffizienz ausgezeichnet.", "Mercedes-Benz investiert aktuell Milliarden in die Erweiterung des Werks für die Produktion von Elektrofahrzeugen."]),
    "historical-gyulai-var-extra": ("Die Burg von Gyula ist ein einzigartiges historisches Denkmal, da sie die einzige vollständig erhaltene gotische Backsteinburg im Karpatenbecken ist. Erbaut im 15. Jahrhundert, trotzte sie über die Jahrhunderte zahlreichen Belagerungen und der osmanischen Besatzung. Die massiven Mauern aus rötlichem Backstein verleihen der Burg ein unverwechselbares Aussehen. Heute fungiert die Festung als Museum mit 24 Ausstellungsräumen, die das Leben im Mittelalter, die Geschichte der Verteidigung und den Alltag in der Burg illustrieren. Besucher können die Waffenkammer, die Schlosskapelle, die Backstube und sogar das Verlies besichtigen. Vom Turm aus bietet sich ein wunderbarer Rundblick über die Stadt Gyula und das benachbarte Burgbad. Im Sommer verwandelt sich der Innenhof in eine stimmungsvolle Bühne für das Burghtheater, das zu den renommiertesten Freilichtfestivals Ungarns zählt.", ["Die Burg wurde zwischen 1405 und 1445 erbaut.", "Im Jahr 1566 hielt die Burg einer 63-tägigen Belagerung durch ein riesiges osmanisches Heer stand.", "Der Baustoff Backstein wurde gewählt, weil es in der Gegend kaum Natursteinvorkommen gab.", "Innerhalb der Mauern befand sich einst eine eigene Münzprägestätte.", "Die Burgkapelle wurde nach der Türkenzeit wieder geweiht und ist heute ein Ort für Hochzeiten.", "Das Burgmuseum zeigt eine seltene Sammlung mittelalterlicher Ofenkacheln.", "Die Burg ist von einem malerischen Wassergraben und einem Park umgeben.", "Gyula ist auch berühmt für seine Wurstspezialitäten, die weltweit exportiert werden."]),
    "historical-szarvasi-szarazmalom-extra": ("Die Trockenmühle von Szarvas ist ein außergewöhnliches technisches Denkmal und eines der wenigen erhaltenen Exemplare dieser Art in Europa. Eine Trockenmühle wird nicht durch Wasser oder Wind, sondern durch Tierkraft – meist Pferde – angetrieben. Das Gebäude in Szarvas stammt aus dem 19. Jahrhundert und besticht durch seine beeindruckende Holzkonstruktion. Unter einem riesigen kegelförmigen Dach befindet sich das gewaltige Zahnradgetriebe, das früher zwei Mahlsteine antrieb. Die Mühle wurde bis in die 1960er Jahre zum Mahlen von Getreide und zum Zerkleinern von Futtermitteln genutzt. Heute ist sie ein Museum, in dem Besucher die faszinierende Mechanik aus nächster Nähe bestaunen können. Bei besonderen Anlässen werden sogar Pferde eingespannt, um die Mühle vorzuführen. Sie ist ein Symbol für die bäuerliche Genialität und die vorindustrielle Arbeitswelt in der ungarischen Puszta.", ["Die Mühle wurde im Jahr 1836 von der Familie Bolza errichtet.", "Das Hauptzahnrad hat einen Durchmesser von über fünf Metern.", "Es handelt sich um eine sogenannte 'Unterantriebs-Mühle'.", "Das Gebäude wurde vollständig aus Eichen- und Kiefernholz ohne Verwendung von Metallnägeln errichtet.", "Die Mühle konnte pro Stunde etwa 40-50 Kilogramm feines Mehl mahlen.", "In ganz Ungarn gibt es nur noch drei solcher Mühlen an ihrem ursprünglichen Standort.", "Die Trockenmühle von Szarvas wurde in den 1970er Jahren originalgetreu restauriert.", "Szarvas beherbergt auch das größte Arboretum Ungarns und den Mini-Ungarn-Park."]),
    "historical-gyulai-almasy-kastely-extra": ("Das Almásy-Schloss in Gyula ist ein prachtvolles Barock- und Klassizistik-Bauwerk, das nach einer umfassenden Restaurierung zu einem der modernsten interaktiven Museen Ungarns geworden ist. Das Schloss war über Generationen Sitz bedeutender Adelsfamilien wie der Harruckern, Wenckheim und Almásy. Was dieses Museum so besonders macht, ist sein Konzept: Statt nur Prunkräume zu zeigen, erzählt es die Geschichte des Schlosses aus zwei Perspektiven – der der Herren und der der Bediensteten. Besucher erfahren durch innovative Technologien, wie der Alltag in der Küche, in den Schlafgemächern oder in den Salons aussah. Das Schloss liegt in einem wunderschönen Park, direkt neben dem berühmten Burgbad von Gyula. Mit seinen eleganten Fassaden, den prächtigen Innenräumen und der fesselnden Erzählweise ist das Almásy-Schloss ein kulturelles Highlight, das die glanzvolle Geschichte des ungarischen Adels lebendig werden lässt.", ["Das Schloss war das erste in Ungarn, in dem ein Theaterstück aufgeführt wurde (1746).", "Hier hielten sich berühmte Persönlichkeiten wie Ferenc Erkel und der Maler Mihály Munkácsy auf.", "Nach der Niederlage im Unabhängigkeitskrieg 1849 legten hier zehn ungarische Generäle ihre Waffen nieder.", "Die interaktive Ausstellung wurde für mehrere internationale Museumspreise nominiert.", "Im Schlossturm befindet sich eine Aussichtsplattform mit Blick auf die Burg Gyula.", "Das Gebäude verfügt über ein einzigartiges Heizungssystem aus dem 19. Jahrhundert.", "Das Schloss beherbergt auch ein elegantes Café und einen Museumsshop mit regionalen Produkten.", "Der Schlosspark ist Teil des Naturschutzgebiets der Stadt Gyula."]),
    "animal-habitat-korosvolgyi-allatpark-extra": ("Der Körös-Tal Tierpark in Szarvas bietet ein besonderes Naturerlebnis im Herzen des Körös-Maros Nationalparks. Auf einer Fläche von mehreren Hektar präsentiert der Park die ursprüngliche Fauna des Karpatenbeckens in weitläufigen, naturnahen Gehegen. Besucher können hier Tiere beobachten, die einst in der ungarischen Puszta und den umliegenden Wäldern heimisch waren, wie den imposanten europäischen Bison, Wölfe, Damhirsche und Wildschweine. Ein besonderer Fokus liegt auf der Vogelwelt der Region; große Volieren beherbergen verschiedene Eulenarten und Greifvögel. Der Park ist so gestaltet, dass er den Tieren viel Rückzugsort bietet, während Besucher auf ruhigen Wanderwegen die Natur genießen können. Das dazugehörige Besucherzentrum informiert über die ökologische Bedeutung des Körös-Tals und bietet Bildungsprogramme für alle Altersgruppen. Ein Besuch hier ist ideal für Naturliebhaber, die Ruhe suchen und die ursprüngliche Tierwelt Ungarns hautnah erleben möchten.", ["Der Tierpark wurde im Jahr 2014 im ehemaligen Schlossgarten der Familie Anna-Liget eröffnet.", "Der europäische Bison ist das schwerste Landsäugetier Europas und ein Highlight des Parks.", "Es gibt einen speziellen Lehrpfad, der die Flora und Fauna der Körös-Auen erklärt.", "Der Park beherbergt auch seltene ungarische Haustierrassen.", "Im Besucherzentrum befindet sich ein großes Aquarium mit Fischen aus den Körös-Flüssen.", "Der Tierpark ist barrierefrei gestaltet und somit für alle Besucher gut zugänglich.", "Regelmäßig werden geführte Touren und Umweltbildungstage für Kinder organisiert.", "Die Umgebung des Parks, das Anna-Liget, ist für seinen jahrhundertealten Baumbestand bekannt."]),
    "industry-csabai-kolbaszgyar-extra": ("Die Wurstfabrik in Békéscsaba ist die Heimat der weltberühmten Csabai-Wurst, einem kulinarischen Wahrzeichen Ungarns. Die Tradition der Wurstherstellung reicht in dieser Region Jahrhunderte zurück und basiert auf der perfekten Mischung aus hochwertigem Schweinefleisch und dem berühmten ungarischen Paprika. In der modernen Produktionsstätte wird heute traditionelles Handwerk mit modernsten Hygienestandards kombiniert, um den einzigartigen Geschmack und die Qualität der Csabai zu bewahren. Die Wurst zeichnet sich durch ihre intensive rote Farbe, ihre angenehme Schärfe und das rauchige Aroma aus. Békéscsaba feiert sein kulinarisches Erbe jedes Jahr mit einem der größten Wurstfestivals Europas, zu dem Zehntausende Besucher strömen. Die Fabrik ist nicht nur ein bedeutender Arbeitgeber, sondern trägt auch dazu bei, dass die ungarische Gastronomie weltweit einen hervorragenden Ruf genießt. Für Feinschmecker ist die Csabai ein unverzichtbarer Bestandteil jeder echten ungarischen Brotzeit.", ["Die Csabai-Wurst ist ein geschütztes 'Hungaricum' und unterliegt strengen Qualitätsregeln.", "Echtes Csabai-Wurstpulver darf nur aus lokal angebautem Paprika bestehen.", "Ein charakteristisches Merkmal ist, dass im Originalrezept kein Schwarzpfeffer verwendet wird.", "Das Wurstfestival in Békéscsaba findet seit 1997 jährlich im Oktober statt.", "Die Wurst wird über Buchenholz geräuchert, um ihr spezielles Aroma zu erhalten.", "Es gibt sowohl milde als auch scharfe Varianten der berühmten Wurst.", "In Békéscsaba gibt es ein eigenes Wurstmuseum, das die Geschichte der Herstellung zeigt.", "Die Csabai-Wurst wird in über 20 Länder weltweit exportiert."]),
    "historical-boldogkoi-var-extra": ("Die Burg Boldogkő ist eine der spektakulärsten Festungen im Nordosten Ungarns, thronend auf einem schmalen Felsgrat im Zemplén-Gebirge. Ihre Silhouette mit dem markanten Aussichtsgang auf dem Felsen ist ein beliebtes Fotomotiv. Die Burg wurde im 13. Jahrhundert nach dem Mongolensturm errichtet, um die Handelswege nach Polen zu schützen. Über die Jahrhunderte wechselte sie oft den Besitzer und wurde mehrfach umgebaut. Heute erwartet Besucher eine liebevoll restaurierte Anlage mit verschiedenen Ausstellungen. Besonders beeindruckend ist die Sammlung historischer Zinnfiguren, die eine der größten ihrer Art in Mitteleuropa ist und berühmte Schlachten der ungarischen Geschichte nachstellt. Ein Spaziergang über den hölzernen Steg auf dem Felsrücken bietet ein atemberaubendes Panorama über das Hernád-Tal. Die Burg Boldogkő verbindet mittelalterliche Romantik mit einer faszinierenden Geologie und ist ein Muss für jeden Wanderer und Geschichtsinteressierten in der Region.", ["Der Name Boldogkő bedeutet übersetzt so viel wie 'Glücklicher Stein'.", "Die Burg wurde auf einem vulkanischen Andesit-Felsen erbaut.", "In der Burg befindet sich eine funktionierende mittelalterliche Schmiede.", "Die Zinnfigurenausstellung umfasst über 1.000 handbemalte Figuren.", "Die Burg diente im 16. Jahrhundert als Zufluchtsort für siebenbürgische Fürsten.", "Unter der Burg befindet sich ein weitläufiges Kellersystem, das einst als Vorratslager diente.", "Im Sommer finden hier regelmäßig Ritterspiele und mittelalterliche Feste statt.", "Die Burg ist Teil der 'Nationalen Burgen- und Schlossprogramms' zur Erhaltung des kulturellen Erbes."]),
    "historical-fuzeri-var-extra": ("Die Burg Füzér liegt auf einem steilen Vulkankegel im nördlichsten Teil Ungarns und gilt als eine der schönsten und am besten restaurierten Burgen des Landes. Ihre weiße Silhouette hebt sich markant von den grünen Wäldern des Zemplén-Gebirges ab. Die Burg hat eine enorme historische Bedeutung: Hier wurde nach der Schlacht von Mohács die ungarische Heilige Krone vor den Osmanen versteckt gehalten. In den letzten Jahren wurde die Oberburg umfassend rekonstruiert, sodass Besucher heute die prachtvolle gotische Kapelle, den Rittersaal und die herrschaftlichen Wohnräume in ihrem einstigen Glanz bewundern können. Der Aufstieg zur Burg ist steil, wird aber mit einem unvergleichlichen Blick über die unberührte Natur Nordungarns belohnt. Füzér ist nicht nur ein Denkmal der Verteidigungsarchitektur, sondern auch ein Symbol für den Stolz und die Widerstandskraft der ungarischen Nation über die Jahrhunderte hinweg.", ["Füzér war eine der ersten privaten Steinburgen Ungarns, erbaut vor dem Mongolensturm 1241.", "Die Heilige Krone wurde hier zwischen 1526 und 1527 für etwa ein Jahr gehütet.", "Die Burgkapelle ist ein Meisterwerk der Frühgotik mit wunderschönen Maßwerkfenstern.", "Der Vulkankegel, auf dem die Burg steht, wurde zum Naturdenkmal erklärt.", "Die Burg wurde 1676 auf Befehl des Kaisers gesprengt und lag fast 300 Jahre in Ruinen.", "Die Rekonstruktion basiert auf detaillierten archäologischen und historischen Forschungen.", "Im Dorf am Fuße der Burg gibt es ein interessantes Heimatmuseum.", "Füzér liegt direkt am Nationalen Fernwanderweg 'Kéktúra'."]),
    "historical-diosgyori-var-extra": ("Die Burg Diósgyőr am Rande von Miskolc ist eine einzigartige 'Erlebnisburg', die Besuchern den Glanz des ungarischen Mittelalters näherbringt. Im 14. Jahrhundert baute König Ludwig der Große die Festung zu einem prächtigen gotischen Schloss um, das fortan als Lieblingsresidenz der ungarischen Königinnen diente – daher auch der Beiname 'Burg der Königinnen'. Im Gegensatz zu vielen anderen Ruinen wurde Diósgyőr in den letzten Jahren großflächig rekonstruiert, wobei moderne Architektur mit historischen Mauern kombiniert wurde. Besucher können heute komplett eingerichtete Räume wie den prunkvollen Rittersaal, die königlichen Gemächer und eine mittelalterliche Küche erleben. Animatoren in historischen Kostümen beleben die Burg und führen altes Handwerk vor. Die vier markanten Ecktürme und der große Turnierplatz im Außenbereich machen die Burg zu einem lebendigen Zentrum für Kultur und Geschichte, das besonders für Familien ein unvergessliches Ziel darstellt.", ["König Ludwig der Große unterzeichnete hier 1381 den Frieden von Turin mit Venedig.", "Die Burg war ein traditionelles Hochzeitsgeschenk für die ungarischen Königinnen.", "Der Rittersaal galt im Mittelalter als einer der größten in Europa.", "Innerhalb der Burg befindet sich eine der größten Panoptikum-Ausstellungen Ungarns.", "In der Mitte des Burghofs steht ein 40 Meter tiefer Brunnen, der direkt in den Felsen geschlagen wurde.", "Die Burgruine wurde in den 1960er Jahren erstmals gesichert und ab 2014 umfassend wiederaufgebaut.", "Jährlich finden hier die 'Historischen Spiele von Diósgyőr' statt.", "Die Burg ist über eine nostalgische Straßenbahnlinie direkt mit dem Zentrum von Miskolc verbunden."]),
    "animal-habitat-miskolci-allatkert-extra": ("Der Zoo von Miskolc, malerisch im Bükk-Gebirge gelegen, ist eine der ältesten zoologischen Einrichtungen Ungarns und bietet ein naturnahes Erlebnis in einer bewaldeten Umgebung. Ursprünglich als Wildpark konzipiert, hat er sich zu einem modernen Zoo entwickelt, der über 120 Tierarten aus fünf Kontinenten beherbergt. Besonders hervorzuheben ist der Fokus auf den Naturschutz und die Haltung bedrohter heimischer Arten. Die Gehege sind großzügig gestaltet und nutzen die natürlichen Gegebenheiten des Geländes, was den Tieren eine stressfreie Umgebung bietet. Ein Highlight für Besucher ist der 'Talweg', der an Wölfen, Luchsen und Braunbären vorbeiführt. Der Zoo ist zudem für sein 'Kulturpark'-Konzept bekannt, das Tierbeobachtung mit Bildung und Entspannung im Wald verbindet. Durch seine Lage direkt am Tor zum Nationalpark Bükk ist der Zoo ein idealer Ausgangspunkt für Wanderungen und ein beliebtes Ziel für Familien, die Natur und Tierwelt gleichermaßen schätzen.", ["Der Zoo wurde bereits im Jahr 1389 als königlicher Wildpark erwähnt.", "In seiner heutigen Form wurde er 1983 als 'Miskolci Vadaspark' neu eröffnet.", "Er beherbergt eine der bedeutendsten Zuchtgruppen für den gefährdeten europäischen Luchs.", "Der Zoo liegt in einem Naturschutzgebiet von hoher biologischer Vielfalt.", "Es gibt ein spezielles Gebäude für pädagogische Zwecke, das Kindern den Wald näherbringt.", "Zu den seltenen exotischen Bewohnern gehören die Sibirischen Tiger und die Afrikanischen Löwen.", "Der Park verfügt über einen Aussichtsturm, von dem aus man weit ins Bükk-Gebirge blicken kann.", "Der Zoo von Miskolc nimmt an zahlreichen internationalen Programmen zur Erhaltung bedrohter Arten (EEP) teil."]),
    "industry-tiszaujvarosi-vegyimuvek-extra": ("Das Chemiewerk in Tiszaújváros ist einer der größten und bedeutendsten Industriekomplexe Ungarns und ein zentraler Akteur in der europäischen Petrochemie. Als Teil der MOL-Gruppe konzentriert sich das Werk auf die Herstellung von Polymeren wie Polyethylen und Polypropylen, die die Grundstoffe für unzählige Kunststoffprodukte weltweit bilden. Die Anlage wurde in den 1950er Jahren gegründet und hat seitdem die Entwicklung der gesamten Region geprägt; die Stadt Tiszaújváros entstand ursprünglich als Wohnort für die Arbeiter des Werks. Heute zeichnet sich der Komplex durch modernste Technologie, hohe Sicherheitsstandards und kontinuierliche Milliardeninvestitionen in neue Produktionsanlagen aus. Ein aktuelles Großprojekt ist der Bau einer Polyol-Anlage, die die Wertschöpfungskette des Unternehmens weiter vertieft. Trotz der industriellen Dimension wird großer Wert auf Umweltmanagement gelegt, um die Auswirkungen auf das nahegelegene Theiß-Ökosystem zu minimieren. Das Werk ist ein unverzichtbarer Wirtschaftsmotor und ein Symbol für die industrielle Leistungsfähigkeit Ungarns.", ["Das Unternehmen hieß früher TVK (Tiszai Vegyi Kombinát).", "Es ist der größte Produzent von Kunststoffen in Ungarn und einer der größten in Mittel- und Osteuropa.", "Über 50 % der Produktion werden in das europäische Ausland exportiert.", "Die neue Polyol-Fabrik ist eine der größten Einzelinvestitionen in der ungarischen Industriegeschichte.", "Das Werk verfügt über ein eigenes Logistikzentrum mit umfangreichem Schienenanschluss.", "Energieeffizienz ist ein Kernziel der aktuellen Modernisierungsstrategie.", "Das Werk bietet hochspezialisierte Arbeitsplätze für Ingenieure und Chemiker aus dem ganzen Land.", "Tiszaújváros wird oft als die 'Hauptstadt der ungarischen Chemieindustrie' bezeichnet."]),
    "historical-szegedi-dom-extra": ("Die Votivkirche von Szeged, auch bekannt als Szegeder Dom, ist ein beeindruckendes neoromanisches Bauwerk und das Wahrzeichen der Stadt an der Theiß. Der Bau wurde nach der verheerenden Flut von 1879 gelobt, als die Bürger von Szeged schworen, eine prächtige Kirche zu errichten, falls die Stadt wieder aufgebaut werden könne. Die markante Fassade aus rotem Backstein mit mit ihren zwei 81 Meter hohen Türmen dominiert den riesigen Domplatz. Das Innere ist überwältigend gestaltet: Farbenfrohe Fresken, goldverzierte Altäre und eine der größten Orgeln Europas prägen das Bild. Besonders bemerkenswert ist das Mosaik der 'Madonna im Pelz von Szeged' über dem Altar. Der Domplatz dient im Sommer als spektakuläre Kulisse für die Szegeder Freilichtspiele, eines der bedeutendsten Theaterfestivals des Landes. Der Dom ist nicht nur ein Ort des Gebets, sondern auch ein Denkmal für den Zusammenhalt und den Wiederaufbauwillen einer ganzen Stadt nach einer Katastrophe.", ["Der Bau begann 1913, wurde aber durch den Ersten Weltkrieg unterbrochen und erst 1930 geweiht.", "Die Domorgel hat über 9.000 Pfeifen und einen einzigartigen Klang.", "Der Domplatz hat die exakt gleiche Fläche wie der Markusplatz in Venedig (ca. 12.000 m²).", "In den Mauern des Doms sind Denkmäler für berühmte ungarische Wissenschaftler und Künstler eingelassen.", "Die zwei Türme können bestiegen werden und bieten einen Panoramablick über Szeged und die Theiß.", "Das Deckenfresko der Madonna zeigt sie in einem typischen Szegeder Pelzmantel und mit Salami-ähnlichen Stickereien.", "Unter der Kirche befindet sich eine weitläufige Unterkirche für Ausstellungen und Gedenkstätten.", "Szeged wird oft als 'Stadt des Sonnenscheins' bezeichnet, was den Besuch des hellen Doms besonders attraktiv macht."]),
    "historical-mora-ferenc-muzeum-extra": ("Das Móra Ferenc Museum in Szeged ist ein bedeutendes kulturelles Zentrum und eines der meistbesuchten Museen Südungarns. Es befindet sich in einem prachtvollen klassizistischen Gebäude direkt am Ufer der Theiß. Benannt ist es nach dem berühmten ungarischen Schriftsteller Ferenc Móra, der viele Jahre lang Direktor des Instituts war. Das Museum beherbergt vielfältige Sammlungen aus den Bereichen Archäologie, Ethnographie, Naturwissenschaften und Bildende Kunst. Besonders bekannt ist es für seine wechselnden Großausstellungen, die oft internationale Themen wie die Kultur der Inka, die Terrakotta-Armee oder das antike Ägypten präsentieren. In den permanenten Ausstellungen erfahren Besucher viel über die Geschichte der Stadt Szeged, die lokale Volkskunst und das Leben an der Theiß. Mit seinem eleganten Vorplatz und der imposanten Freitreppe ist das Museum nicht nur ein Ort der Bildung, sondern auch ein architektonisches Juwel, das das Stadtbild von Szeged maßgeblich prägt.", ["Das Museumsgebäude wurde im Jahr 1896 im Rahmen der Millenniumsfeierlichkeiten eröffnet.", "Ferenc Móra war nicht nur Schriftsteller, sondern auch ein leidenschaftlicher Archäologe.", "Das Museum besitzt eine bedeutende Goldfund-Sammlung aus der Zeit der Völkerwanderung.", "Im Keller des Museums befindet sich eine Ausstellung zur Geschichte des Handwerks in Szeged.", "Die Freitreppe des Museums ist ein beliebter Treffpunkt für Studenten der nahen Universität.", "Eine spezielle Abteilung widmet sich dem Leben und Werk von Ferenc Móra.", "Das Museum ist eng mit der wissenschaftlichen Forschung in der Region verbunden.", "Von den oberen Etagen hat man einen herrlichen Blick auf die Theiß und die Belvárosi-Brücke."]),
    "historical-csongradi-ovaros-extra": ("Die Altstadt von Csongrád ist ein einzigartiges Denkmalensemble, das die Atmosphäre eines traditionellen Fischerdorfes an der Theiß bewahrt hat. Das Viertel besteht aus Dutzenden von weiß getünchten, reetgedeckten Bauernhäusern, die organisch entlang der Uferlinie gewachsen sind. Diese Häuser wurden ursprünglich von Fischern und Kleinbauern bewohnt und vermitteln heute einen lebendigen Eindruck von der ländlichen Architektur des 18. und 19. Jahrhunderts. Viele der Gebäude fungieren heute als Ferienhäuser, Museen oder Werkstätten für Kunsthandwerker, was dem Viertel eine lebendige, kreative Aura verleiht. Die engen, oft unbefestigten Gassen und die Nähe zum Fluss machen einen Spaziergang hier zu einer Reise in die Vergangenheit. Die Altstadt von Csongrád steht unter nationalem Denkmalschutz und ist ein herausragendes Beispiel für die Bewahrung des kulturellen Erbes in Ungarn, weit weg vom hektischen modernen Stadtleben.", ["Das Viertel wird oft als 'lebendes Freilichtmuseum' (Skanzen) bezeichnet.", "Insgesamt stehen 37 Gebäude unter Einzeldenkmalschutz.", "Die Reetdächer müssen alle paar Jahrzehnte von spezialisierten Handwerkern erneuert werden.", "Csongrád war im Mittelalter ein bedeutender Verwaltungs- und Handelsplatz.", "In einigen Häusern kann man heute wie vor 150 Jahren übernachten, allerdings mit modernem Komfort.", "Die Stadt liegt am Zusammenfluss von Körös und Theiß.", "Jährlich findet hier das 'Weinfestival von Csongrád' statt, das auch die Altstadt belebt.", "Die Region ist bekannt für ihren Sandboden-Wein, insbesondere den Cadarca."]),
    "animal-habitat-szegedi-vadaspark-extra": ("Der Szegeder Wildpark (Szegedi Vadaspark) ist flächenmäßig der größte Zoo Ungarns und zeichnet sich durch seine weitläufigen, naturnahen Waldgehege aus. Im Gegensatz zu klassischen Stadtzoos legt man hier großen Wert darauf, den Tieren viel Raum und eine Umgebung zu bieten, die ihrem natürlichen Habitat so nah wie möglich kommt. Der Zoo ist geografisch gegliedert und beherbergt seltene und bedrohte Tierarten aus aller Welt, mit einem besonderen Schwerpunkt auf der Fauna Südamerikas. Besucher können hier Ameisenbären, Pumas, Tapire und verschiedene Affenarten beobachten. Ein Highlight ist das moderne Löwen- und Tigergehege sowie das Elefantenhaus. Der Park ist zudem für seine Naturschutzprojekte und die Rettung verletzter Wildtiere bekannt. Durch die dichte Bewaldung ist der Besuch auch im heißen Sommer von Szeged sehr angenehm. Der Vadaspark bietet eine perfekte Mischung aus Abenteuer, Bildung und Entspannung in der Natur.", ["Der Wildpark wurde im Jahr 1989 eröffnet.", "Er erstreckt sich über eine Fläche von rund 45 Hektar.", "Besonders erfolgreich ist der Zoo bei der Zucht von Krallenaffen und anderen seltenen Primaten.", "Es gibt ein modernes Besucherzentrum mit interaktiven Ausstellungen zum Thema Artenschutz.", "Der Zoo beherbergt Tiere, die in anderen ungarischen Zoos oft nicht zu sehen sind, wie die fossas aus Madagaskar.", "Regelmäßig finden pädagogische Programme und Schaufütterungen statt.", "Ein großer Teil des Geländes besteht aus einem natürlichen Eichen- und Kiefernwald.", "Der Vadaspark ist Mitglied im Weltverband der Zoos und Aquarien (WAZA)."]),
    "industry-szegedi-paprika-extra": ("Die Paprikaverarbeitung in Szeged ist ein wesentlicher Teil der ungarischen Identität und Gastronomie. Szeged gilt zusammen mit Kalocsa als das Zentrum des Paprikaanbaus weltweit. Das hier produzierte Gewürzpulver, das 'rote Gold', ist berühmt für seine leuchtende Farbe, sein intensives Aroma und die feine Abstimmung zwischen Süße und Schärfe. Die Tradition begann im 18. Jahrhundert, als der Paprika zunächst als Zierpflanze und später als Heilmittel und Gewürz an Bedeutung gewann. In den Fabriken von Szeged wird der Paprika nach der Ernte getrocknet und in speziellen Mühlen fein gemahlen. Die strengen Qualitätskontrollen stellen sicher, dass nur bester Paprika den Namen 'Szegedi Paprika' tragen darf. Für Besucher gibt es in der Stadt Museen, die den Weg der Pflanze vom Feld bis in den Kochtopf zeigen. Paprika aus Szeged ist ein unverzichtbares Souvenir und die wichtigste Zutat für klassische ungarische Gerichte wie Pörkölt oder Gulaschsuppe.", ["Szegedi Paprika ist eine geschützte Ursprungsbezeichnung der EU.", "Der ungarische Wissenschaftler Albert Szent-Györgyi isolierte in Szeged Vitamin C aus Paprikaschoten.", "Für seine Entdeckung erhielt Szent-Györgyi 1937 den Nobelpreis für Medizin.", "Es gibt verschiedene Qualitätsstufen, von 'Edelsüß' bis 'Rosenpaprika' (scharf).", "Das sonnige Klima der Region bietet ideale Bedingungen für das Wachstum der Pflanzen.", "Früher wurde der Paprika an den Wänden der Bauernhäuser zum Trocknen aufgehängt, was ein typisches Landschaftsbild war.", "In Szeged gibt es ein spezielles Pick-Salami- und Paprika-Museum.", "Jährlich werden in der Region Tausende Tonnen Paprika geerntet und verarbeitet."]),
    "historical-bory-var-extra": ("Die Bory-Burg in Székesfehérvár ist ein absolut einzigartiges architektonisches Kuriosum und ein Denkmal der ewigen Liebe. Der Architekt und Bildhauer Jenő Bory errichtete die Burg über einen Zeitraum von fast 40 Jahren (1923-1959) weitgehend im Alleingang. Das Besondere: Als Baumaterial diente hauptsächlich Beton, ein damals moderner Stoff, den Bory meisterhaft für Skulpturen, Säulen und Türme einsetzte. Die Burg ist ein eklektisches Labyrinth aus Türmen, Arkaden, Innenhöfen und Galerien, geschmückt mit Hunderten von Statuen und Gemälden, die Bory und seine Frau Ilona Komocsin schufen. Überall finden sich Liebesgedichte und Inschriften, die seiner Gattin gewidmet sind. Die Burg wirkt wie aus einem Märchen entsprungen und bietet hinter jeder Ecke neue Details zum Entdecken. Heute ist sie ein privates Museum, das von den Nachkommen gepflegt wird und Besucher aus der ganzen Welt durch seine fantasievolle und persönliche Atmosphäre verzaubert.", ["Jenő Bory war Professor an der Kunstakademie in Budapest.", "Die Burg wurde im Guinness-Buch der Rekorde als das größte Gebäude erwähnt, das eine Person allein erbaut hat.", "Bory arbeitete oft nur in den Sommerferien an seiner Burg.", "Der Baustil mischt Elemente der Romanik, Gotik und Renaissance mit modernem Betonbau.", "Hinter der Burg befindet sich ein wunderschöner Garten mit weiteren Skulpturen.", "Das Gebäude überstand den Zweiten Weltkrieg trotz einiger Treffer relativ gut.", "Die 'Halle der Elefanten' im Innenhof ist eines der bekanntesten Fotomotive.", "Viele der Skulpturen in der Burg sind Abgüsse von Werken, die Bory für öffentliche Plätze in Ungarn schuf."]),
    "historical-martonvasari-kastely-extra": ("Das Schloss Brunszvik in Martonvásár ist ein bezauberndes neogótisches Herrenhaus, das vor allem durch seine Verbindung zu Ludwig van Beethoven Weltruhm erlangte. Die Familie Brunszvik war eng mit dem Komponisten befreundet, der das Schloss mehrfach besuchte und dort einige seiner berühmtesten Werke vollendete. Das heutige Aussehen des Schlosses mit seinen markanten Türmchen und Spitzbogenfenstern stammt aus einer Umgestaltung im späten 19. Jahrhundert. Im Inneren befindet sich das Beethoven-Gedenkmuseum, das persönliche Gegenstände und Dokumente des Genies präsentiert. Das Schloss ist von einem prächtigen, 70 Hektar großen englischen Garten umgeben, der mit einem künstlichen See und einer Insel aufwartet. Auf dieser Insel finden im Sommer regelmäßig die berühmten Beethoven-Konzerte statt, die Musikliebhaber in die romantische Kulisse von Martonvásár locken. Es ist ein Ort, an dem sich Architektur, Musik und Natur auf harmonische Weise vereinen.", ["Das Schloss wurde ursprünglich im Barockstil erbaut und später im Tudor-Stil neogotisch umgestaltet.", "Beethoven gab den Brunszvik-Töchtern Therese und Josephine Klavierunterricht.", "Einige Historiker vermuten, dass Therese oder Josephine Brunszvik die 'unsterbliche Geliebte' Beethovens war.", "Therese Brunszvik gründete in Ungarn den ersten Kindergarten in Mitteleuropa.", "Der Schlosspark beherbergt viele seltene Baumarten aus aller Welt.", "Das Gebäude beherbergt heute auch ein Forschungsinstitut für Landwirtschaft der Ungarischen Akademie der Wissenschaften.", "Der künstliche See wird vom kleinen Fluss Szent László gespeist.", "Das Schloss gilt als eines der romantischsten Ausflugsziele in der Nähe von Budapest."]),
    "historical-nadasdy-kastely-extra": ("Das Schloss Nádasdy in Nádasdladány ist ein architektonisches Juwel, das durch seinen außergewöhnlichen Tudor-Stil aus der Masse ungarischer Schlösser heraussticht. Erbaut in den 1870er Jahren für Graf Ferenc Nádasdy, erinnert es mit seinen Zinnen, Türmen und der dunklen Steinoptik an englische Herrenhäuser. Die Innenausstattung war für die damalige Zeit revolutionär: Das Schloss verfügte bereits über eine Zentralheizung, Gasbeleuchtung und ein modernes Telegrafensystem. Besonders sehenswert ist die prachtvolle Bibliothek mit ihrer kunstvoll geschnitzten Holzvertäfelung und der Ahnenhalle, in der lebensgroße Porträts der Familie Nádasdy hängen. Das Schloss war über Jahrzehnte verfallen, wurde aber in den letzten Jahren aufwendig restauriert und erstrahlt nun wieder in altem Glanz. Der weitläufige Landschaftspark mit seinem See bietet eine friedliche Kulisse für dieses Stück England inmitten der ungarischen Landschaft, das die Geschichte einer der bedeutendsten Adelsfamilien des Landes erzählt.", ["Der Architekt István Linzbauer entwarf das Schloss nach den Wünschen des Grafen im englischen Stil.", "Graf Ferenc Nádasdy baute das Schloss auch als Denkmal für seine früh verstorbene Frau Ilona Zichy.", "Die Ahnenhalle enthält eine der bedeutendsten Porträtsammlungen des ungarischen Adels.", "Die Bibliothek gilt als eine der schönsten privaten Bibliotheken in Mitteleuropa.", "Das Schloss besaß eine eigene Schmiede und eine Gärtnerei auf dem Gelände.", "Nach dem Zweiten Weltkrieg wurde das Gebäude als Schule und Postamt genutzt, was zu Schäden führte.", "Die Restaurierung im Rahmen des Nationalen Schlossprogramms wurde 2021 abgeschlossen.", "Die Region um Nádasdladány ist auch für ihre Porzellanmanufaktur in Herend bekannt, die nicht weit entfernt liegt."]),
    "animal-habitat-velencei-madarrezervatum-extra": ("Das Vogelreservat am Velence-See ist ein bedeutendes Naturschutzgebiet am westlichen Ende des zweitgrößten natürlichen Sees Ungarns. Dieses ausgedehnte Schilf- und Sumpfgebiet bietet idealen Lebensraum für eine unglaubliche Vielfalt an Wasservögeln. Über 200 Vogelarten wurden hier bereits gesichtet, darunter seltene Reiher, Löffler und verschiedene Entenarten. Das Reservat ist ein wichtiger Rastplatz für Zugvögel auf ihrer Reise über den europäischen Kontinent. Um die empfindliche Fauna zu schützen, ist der Kern des Reservats für die Öffentlichkeit gesperrt, doch von Beobachtungstürmen am Rand und bei geführten Bootstouren durch die Schilfkanäle können Besucher die beeindruckende Tierwelt erleben. Der Velence-See selbst ist bekannt für sein flaches, warmes Wasser und ist im Sommer ein beliebtes Urlaubsziel. Das Reservat bildet dazu einen wichtigen ökologischen Kontrapunkt und bewahrt die ursprüngliche Wildnis dieser Region für künftige Generationen.", ["Das Reservat wurde im Jahr 1958 unter Schutz gestellt.", "Es umfasst eine Fläche von etwa 420 Hektar, hauptsächlich Schilfgebiete.", "Besonders im Frühjahr und Herbst sind hier riesige Schwärme von Graugänsen zu beobachten.", "Der Velence-See ist einer der wärmsten Seen Europas, was die Algenbildung und Nahrungskette begünstigt.", "Das Reservat gehört zum Ramsar-Gebiet, einem internationalen Abkommen zum Schutz von Feuchtgebieten.", "An den Ufern gibt es spezielle Lehrpfade, die über die Ökologie des Sees informieren.", "Manchmal können sogar Seeadler bei der Jagd über dem Wasser beobachtet werden.", "Das Gebiet ist auch für seine reiche Insekten- und Amphibienwelt von großer Bedeutung."]),
    "industry-dunaujvarosi-vasmu-extra": ("Das Hüttenwerk in Dunaújváros, heute als Liberty Dunaújváros bekannt, ist das größte integrierte Stahlwerk Ungarns und ein Symbol der sozialistischen Industrialisierung des Landes. Die Stadt Dunaújváros wurde in den 1950er Jahren unter dem Namen Stalinstadt als Modellstadt um das neu errichtete Werk herum gebaut. Das Werk umfasst den gesamten Produktionsprozess von der Kokerei über Hochöfen bis hin zu Walzwerken. Über Jahrzehnte war es der wichtigste Stahllieferant für die ungarische Fahrzeug- und Bauindustrie. Nach der Wende durchlief das Werk mehrere Privatisierungen und Krisen, blieb aber ein unverzichtbarer Wirtschaftsfaktor für die gesamte Region. Heute steht das Unternehmen vor der Herausforderung der Dekarbonisierung und der Umstellung auf 'grünen Stahl'. Die monumentale Industriearchitektur und die schiere Größe des Geländes sind beeindruckend und erzählen viel über die Wirtschaftsgeschichte Ungarns im 20. Jahrhundert.", ["Der Grundstein für das Werk wurde im Jahr 1950 gelegt.", "Dunaújváros hieß von 1951 bis 1961 Sztálinváros (Stalinstadt).", "Das Werk verfügt über einen eigenen Hafen an der Donau für den Rohstofftransport.", "Es war das erste Werk in Ungarn, das die kontinuierliche Stranggießtechnik einführte.", "Die Produktionskapazität liegt bei über einer Million Tonnen Rohstahl pro Jahr.", "Das Werk ist der größte Arbeitgeber in der Region Mitteltransdanubien.", "In der Stadt gibt es ein interessantes Skulpturenhaus-Museum, das die lokale Industriegeschichte zeigt.", "Aktuelle Pläne sehen den Bau von Elektrolichtbogenöfen vor, um die CO2-Emissionen massiv zu senken."]),
    "historical-pannonhalmi-apatsag-extra": ("Die Erzabtei Pannonhalma, hoch oben auf dem Martinsberg thronend, ist eines der bedeutendsten spirituellen und kulturellen Zentren Ungarns und seit 1996 UNESCO-Weltkulturerbe. Die Benediktinerabtei wurde im Jahr 996 gegründet und ist damit fast so alt wie der ungarische Staat selbst. Die Architektur vereint Stilepochen von der Romanik bis zum Klassizismus. Besonders beeindruckend ist die monumentale Basilika mit ihrer mystischen Unterkirche und die weltberühmte Bibliothek, die über 400.000 Bände beherbergt, darunter das Gründungsdokument der Abtei Tihany, das die ersten schriftlichen ungarischen Wörter enthält. Heute ist Pannonhalma eine lebendige Gemeinschaft, die Tradition und Moderne verbindet: Die Mönche führen ein renommiertes Gymnasium, produzieren preisgekrönte Weine und Kräuterprodukte und betreiben ein modernes Besucherzentrum. Ein Besuch bietet tiefe Einblicke in die ungarische Geschichte, Religion und die friedliche Atmosphäre eines Ortes, der seit über tausend Jahren ein Ort des Gebets und des Lernens ist.", ["Pannonhalma gilt als der Ort, an dem der heilige Martin von Tours geboren wurde.", "Die Abtei feierte 1996 ihr 1000-jähriges Bestehen, im selben Jahr wie der Besuch von Papst Johannes Paul II.", "In der Bibliothek befindet sich das älteste schriftliche Denkmal der ungarischen Sprache.", "Das Kloster verfügt über ein eigenes Weingut, das die jahrhundertealte Tradition fortführt.", "Die umliegenden Lavendelfelder und der Kräutergarten sind im Sommer eine große Attraktion.", "Die Abtei betreibt eines der besten Gymnasien des Landes mit Internatsbetrieb.", "Das Arboretum von Pannonhalma beherbergt Hunderte seltene Pflanzenarten.", "Die moderne Architektur des Besucherzentrums und des Weinguts wurde mehrfach ausgezeichnet."]),
    "historical-soproni-tuztorony-extra": ("Der Feuerturm (Tűztorony) ist das unumstrittene Wahrzeichen von Sopron und ein Symbol für die Treue der Stadt zu Ungarn. Der Turm steht auf römischen Fundamenten und seine Architektur spiegelt verschiedene Epochen wider: Der untere, quadratische Teil ist romanisch, der mittlere zylindrisch-gotisch und die charakteristische barocke Kuppel mit der Aussichtsgalerie stammt aus dem 17. Jahrhundert. Ursprünglich diente der Turm den Stadtwächtern zur Beobachtung von Bränden und herannahenden Feinden. Besonders bedeutsam ist das 'Tor der Treue' am Fuße des Turms, das an die Volksabstimmung von 1921 erinnert, bei der sich Sopron für den Verbleib bei Ungarn und gegen den Anschluss an Österreich entschied. Besucher können die 119 Stufen zur Galerie erklimmen und werden mit einem fantastischen Ausblick über die historische Altstadt von Sopron bis hin zu den Alpen und dem Neusiedler See belohnt.", ["Der Turm ist 58 Meter hoch.", "Das 'Tor der Treue' (Hűségkapu) wurde 1928 zum Gedenken an die Abstimmung errichtet.", "Die römischen Fundamente gehören zum einstigen Nordtor der Stadt Scarbantia.", "Im Turm arbeiteten früher Trompeter, die Signale bei Gefahr gaben oder die Zeit verkündeten.", "Nach dem großen Stadtbrand von 1676 erhielt der Turm seine heutige barocke Haube.", "Das Soproner Stadtwappen über dem Tor zeigt die Inschrift 'Civitas Fidelissima' (Treueste Stadt).", "Der Turm beherbergt eine kleine Ausstellung zur Stadtgeschichte.", "Die Glocken des Turms schlagen jede Viertelstunde."]),
    "historical-nagycenki-szechenyi-kastely-extra": ("Das Schloss Széchenyi in Nagycenk war der Wohnsitz von Graf István Széchenyi, einer der bedeutendsten Persönlichkeiten der ungarischen Geschichte, bekannt als der 'größte Ungarn'. Das Schloss ist ein elegantes klassizistisches Gebäude, das heute ein Gedenkmuseum beherbergt, das das Leben und Wirken Széchenyis sowie die Modernisierung Ungarns im 19. Jahrhundert dokumentiert. Besucher können die persönlichen Räume der Familie besichtigen und mehr über Széchenyis Beiträge zur Donauregulierung, zum Brückenbau (Kettenbrücke) und zur Gründung der Akademie der Wissenschaften erfahren. Das Schloss ist von einer prachtvollen Parkanlage umgeben, deren Highlight die 2,6 Kilometer lange, geschützte Lindenallee ist, die Széchenyis Vorfahren anlegten. In der Nähe befindet sich auch das Mausoleum der Familie Széchenyi, ein wichtiger nationaler Wallfahrtsort. Ein Besuch in Nagycenk ist eine Hommage an einen Mann, dessen Visionen das moderne Ungarn maßgeblich geformt haben.", ["Das Schloss wurde ursprünglich im 18. Jahrhundert erbaut und von István Széchenyi modernisiert.", "Hier wurde die erste Pferdeeisenbahn Ungarns auf dem Schlossgelände getestet.", "Die Lindenallee besteht aus über 400 Bäumen und steht unter Naturschutz.", "Das Mausoleum in Nagycenk ist die letzte Ruhestätte von István Széchenyi.", "Das Gedenkmuseum wurde bereits 1973 eröffnet.", "Im Park befindet sich auch eine Museumseisenbahn, die besonders bei Kindern beliebt ist.", "Széchenyi führte im Schloss moderne landwirtschaftliche Methoden und Maschinen ein.", "Das Schloss liegt unweit der Grenze zu Österreich und ist Teil des UNESCO-Kulturerbes Fertő/Neusiedler See."]),
    "animal-habitat-ferto-hansag-park-extra": ("Der Nationalpark Fertő-Hanság umfasst das ungarische Gebiet des Neusiedler Sees und die angrenzenden Hanság-Sümpfe. Es ist eine einzigartige grenzüberschreitende geschützte Landschaft, die gemeinsam mit dem österreichischen Nationalpark Neusiedler See-Seewinkel verwaltet wird. Das Gebiet ist geprägt von riesigen Schilfgürteln, Salzsteppen und flachen Wasserflächen, die ein Paradies für Vögel darstellen. Über 300 Vogelarten nutzen den See als Brut- oder Rastplatz, was ihn zu einem der bedeutendsten ornithologischen Standorte Europas macht. Auch seltene Pflanzen und traditionelle ungarische Haustierrassen wie das Steppenrind und das Wollschwein (Mangalica) sind hier zu finden. Besucher können die Natur auf gut ausgebauten Radwegen, von Beobachtungstürmen aus oder bei geführten Kanutouren durch das Schilf entdecken. Die Region ist zudem für ihre Weine und die reiche Kulturgeschichte bekannt, was 2001 zur Aufnahme in das UNESCO-Welterbe führte.", ["Der Neusiedler See ist der westlichste Steppensee Eurasiens und extrem flach (max. 1,8 m tief).", "Der Nationalpark wurde in seiner heutigen Form 1991 gegründet.", "Etwa 80 % der Seefläche sind mit Schilf bedeckt.", "Das Gebiet ist ein wichtiger Lebensraum für den Großen Silberreiher, das Symbol des ungarischen Naturschutzes.", "In der Hanság-Region gibt es noch ursprüngliche Erlenbruchwälder.", "Das Besucherzentrum 'Kócsagvár' in Sarród ist eines der größten mit Schilf gedeckten Gebäude Ungarns.", "Der See ist ein wichtiges Revier für Segler und Windsurfer.", "Die Region ist berühmt für ihre reiche Flora, darunter viele Orchideenarten."]),
    "industry-audi-gyor-extra": ("Audi Hungaria in Győr ist eines der größten und erfolgreichsten Unternehmen Ungarns sowie eines der bedeutendsten Motorenwerke der Welt. Seit der Gründung im Jahr 1993 hat sich der Standort zu einem zentralen Pfeiler des globalen Audi- und Volkswagen-Produktionsnetzwerks entwickelt. In Győr werden nicht nur Millionen von Hightech-Motoren für fast alle Marken des Konzerns gefertigt, sondern auch komplette Fahrzeuge wie der Audi Q3 und der TT. Das Werk zeichnet sich durch höchste technologische Standards, innovative Produktionsmethoden und eine starke Ausrichtung auf Elektromobilität aus – so werden hier auch die E-Antriebe für die neuen Audi e-tron Modelle produziert. Audi ist der größte Exporteur Ungarns und ein wichtiger Partner für Wissenschaft und Ausbildung in der Region, was sich in der engen Zusammenarbeit mit der Széchenyi István Universität zeigt. Die Präsenz von Audi hat Győr zu einem der dynamischsten Industriezentren Mitteleuropas gemacht.", ["Seit 1993 wurden in Győr bereits über 40 Millionen Motoren produziert.", "Fast jeder zweite Audi weltweit hat einen Motor aus ungarischer Produktion.", "Über 12.000 Mitarbeiter sind direkt am Standort beschäftigt.", "Das Areal umfasst eine Fläche von über 5 Millionen Quadratmetern.", "Audi Hungaria ist seit mehreren Jahren CO2-neutral in der Bilanz.", "Das Werk verfügt über die größte Photovoltaik-Dachanlage Europas.", "In Győr befindet sich auch eine bedeutende Abteilung für Werkzeugbau.", "Das Werk ist der größte Motorenhersteller der Welt unter einem Dach."]),
    "historical-debreceni-egyetem-extra": ("Das Hauptgebäude der Universität Debrecen ist ein monumentales architektonisches Meisterwerk und das Symbol für die reiche Bildungstradition der 'reformierten Hauptstadt' Ungarns. Errichtet in den 1930er Jahren im neobarocken Stil, beeindruckt es durch seine gewaltige Fassade und den herrschaftlichen Vorplatz mit seinem großen Brunnen. Im Inneren führt eine prächtige Treppe in die Aula, die mit farbenfrohen Glasfenstern geschmückt ist, welche die Fakultäten und die Geschichte der Universität darstellen. Die Universität Debrecen ist eine der ältesten und renommiertesten Hochschulen des Landes, deren Wurzeln bis in das Jahr 1538 (Reformiertes Kollegium) zurückreichen. Das Gebäude liegt eingebettet in den malerischen Großen Wald (Nagyerdő) und bildet zusammen mit dem Botanischen Garten einen beeindruckenden Campus. Es ist nicht nur ein Ort der Wissenschaft, sondern auch ein kulturelles Zentrum, das die geistige Elite Ungarns über Jahrhunderte geprägt hat.", ["Das Hauptgebäude wurde 1932 eingeweiht.", "Die Universität hat heute über 30.000 Studenten, darunter viele aus dem Ausland.", "Die Glasfenster in der Aula wurden von dem berühmten Künstler Miksa Róth entworfen.", "Debrecen wird oft das 'Calvinistische Rom' genannt, was die Bedeutung der Universität unterstreicht.", "Hinter dem Gebäude befindet sich ein weitläufiger Botanischer Garten mit seltenen Pflanzen.", "Die Universität verfügt über eine der größten Bibliotheken Ungarns.", "Im Sommer finden auf dem Platz vor der Universität beliebte Lichtshows und Konzerte statt.", "Die medizinische Fakultät der Universität genießt weltweit einen exzellenten Ruf."]),
    "historical-hortobagyi-pasztormuzeum-extra": ("Das Hirtenmuseum in Hortobágy ist das Herzstück des Hortobágy-Nationalparks, der größten Puszta-Region Mitteleuropas. Es ist in einem ehemaligen, imposanten Pferdestall aus dem 18. Jahrhundert untergebracht, der bereits durch seine Architektur beeindruckt. Das Museum widmet sich der jahrhundertealten Tradition des Hirtenlebens in der Puszta und zeigt auf anschauliche Weise den Alltag, die Trachten und die Werkzeuge der Csikós (Pferdehirten), Gulyás (Rinderhirten) und Juhász (Schafhirten). Besucher erfahren, wie diese Männer unter extremen Wetterbedingungen lebten und welche tiefe Verbindung sie zu ihren Tieren und der weiten Landschaft hatten. Die Ausstellung kombiniert historische Artefakte mit lebensgroßen Figuren und vermittelt so ein lebendiges Bild einer verschwindenden Welt. Direkt neben dem Museum befindet sich die berühmte Neunbögige Brücke, ein weiteres Wahrzeichen der Region, die den Geist der ungarischen Puszta perfekt verkörpert.", ["Das Museumsgebäude diente ursprünglich als Wagenstation und Stall an der Salzstraße.", "Hortobágy ist seit 1999 UNESCO-Weltkulturerbe.", "Im Museum sind die kunstvoll verzierten 'Szűr' (Hirtenmäntel) aus Filz zu bewundern.", "Die Csikós von Hortobágy sind weltberühmt für ihre Reitkünste, insbesondere die 'Ungarische Post'.", "Das Gebäude steht unter Denkmalschutz und wurde mehrfach originalgetreu restauriert.", "In der Nähe kann man das traditionelle Gericht 'Slambuc' probieren, das typisch für die Hirten war.", "Hortobágy ist auch ein bedeutender Ort für den Kranichzug im Herbst.", "Das Museum bietet auch Einblicke in die traditionelle Handwerkskunst wie die Lederverarbeitung."]),
    "historical-deri-muzeum-extra": ("Das Déri-Museum in Debrecen ist eines der bedeutendsten Museen Ungarns und beherbergt eine außergewöhnlich vielseitige Sammlung von Weltrang. Das prachtvolle neobarocke Gebäude wurde speziell für die Schenkung des Seidenfabrikanten Frigyes Déri errichtet, der seine riesige Kunst- und Antiquitätensammlung der Stadt vermachte. Das unumstrittene Highlight des Museums ist die monumentale Christus-Trilogie des Malers Mihály Munkácsy ('Christus vor Pilatus', 'Ecce Homo' und 'Golgatha'), die Besucher in einem speziell gestalteten Saal tief beeindruckt. Darüber hinaus bietet das Museum faszinierende Einblicke in die ägyptische Archäologie, die Kultur des Fernen Ostens und die Lokalgeschichte von Debrecen. Die Ausstellungen sind modern und interaktiv gestaltet, was das Museum zu einem Erlebnis für alle Altersgruppen macht. Mit seinem kunstvollen Garten und den Statuen davor ist das Déri-Museum ein kultureller Fixpunkt, der Debrecens Status als geistiges Zentrum Ostungarns untermauert.", ["Das Museum wurde im Jahr 1930 feierlich eröffnet.", "Frigyes Déri sammelte Kunstwerke aus aller Welt, von Ägypten bis Japan.", "Die Munkácsy-Trilogie ist eines der bedeutendsten Werke der ungarischen Malerei des 19. Jahrhunderts.", "Im Museum befindet sich eine echte ägyptische Mumie in einem reich verzierten Sarkophag.", "Die völkerkundliche Abteilung zeigt wertvolle Stücke aus der Puszta-Region.", "Vor dem Museum stehen vier berühmte Bronzestatuen von Ferenc Medgyessy, die Kunst und Wissenschaft symbolisieren.", "Die Sammlung umfasst auch eine bedeutende Waffensammlung aus verschiedenen Epochen.", "Das Museum wurde in den letzten Jahren umfassend modernisiert und ist barrierefrei."]),
    "animal-habitat-nagyerdei-kulturpark-extra": ("Der Nagyerdei Kulturpark in Debrecen vereint den ersten Zoo Ungarns außerhalb der Hauptstadt mit einem traditionsreichen Vergnügungspark. Er liegt idyllisch im Herzen des Großen Waldes (Nagyerdő), dem ersten Naturschutzgebiet des Landes. Der Zoo beherbergt rund 170 Tierarten aus allen fünf Kontinenten, wobei ein besonderer Schwerpunkt auf dem Artenschutz und der Umweltbildung liegt. Besucher können Giraffen, Tiger und exotische Vögel in einer grünen, schattigen Umgebung beobachten. Direkt angeschlossen ist der Vergnügungspark, der mit nostalgischen Fahrgeschäften wie einem historischen Riesenrad und einer charmanten Kindereisenbahn vor allem Familien begeistert. Diese Kombination aus Tierbeobachtung und Spielvergnügen macht den Kulturpark zu einem der beliebtesten Freizeitangebote in Ostungarn. Der Park ist zudem Schauplatz zahlreicher Veranstaltungen, insbesondere während des berühmten Debrecener Blumenkarnivals im August.", ["Der Zoo wurde im Jahr 1958 eröffnet.", "Er war der erste Tiergarten des Landes, der außerhalb von Budapest gegründet wurde.", "Der Vergnügungspark (Vidámpark) wurde 1960 mit dem Zoo vereinigt.", "Das Riesenrad bietet einen schönen Blick über die Baumkronen des Großen Waldes.", "Der Park beherbergt seltene Tierarten wie den Roten Panda und den Nordafrikanischen Strauß.", "Ein Highlight ist das Palmenhaus mit exotischen Pflanzen und Reptilien.", "Die Anlage ist eng mit dem Botanischen Garten der Universität Debrecen verbunden.", "Jährlich besuchen über 100.000 Menschen den Kulturpark."]),
    "industry-bmw-debrecen-extra": ("Das BMW Werk in Debrecen ist eines der zukunftsträchtigsten Industrieprojekte in Europa und markiert einen Meilenstein für die BMW Group. Es ist das weltweit erste Werk des Automobilherstellers, das konsequent nach dem Prinzip der 'iFACTORY' geplant wurde – mit dem Ziel, eine CO2-freie Produktion durch den Verzicht auf fossile Brennstoffe zu erreichen. Ab Mitte der 2020er Jahre soll hier die 'Neue Klasse', eine völlig neue Generation von vollelektrischen Fahrzeugen, vom Band laufen. Das Werk setzt Maßstäbe in Sachen Digitalisierung, Nachhaltigkeit und Flexibilität. Mit einer Investitionssumme von über zwei Milliarden Euro und der Schaffung Tausender Arbeitsplätze ist das Projekt von enormer Bedeutung für die ungarische Wirtschaft und macht Debrecen zu einem globalen Zentrum der modernen E-Mobilität. Das Werk umfasst alle Produktionsschritte vom Presswerk bis zur Montage und wird durch eine eigene Batteriezellfertigung ergänzt, was die strategische Bedeutung des Standorts unterstreicht.", ["Die Bauentscheidung für Debrecen wurde im Jahr 2018 bekannt gegeben.", "Es ist das erste neue BMW Werk in Europa seit der Eröffnung von Leipzig im Jahr 2005.", "Das Werk wird komplett ohne Erdgas betrieben und nutzt ausschließlich regenerative Energien.", "Das Areal umfasst eine Fläche von rund 400 Hektar im Nordwesten von Debrecen.", "Über 1.500 direkte Arbeitsplätze entstehen in der ersten Phase der Produktion.", "BMW kooperiert eng mit der Universität Debrecen zur Ausbildung von Fachkräften.", "In Debrecen werden auch die Hochvoltbatterien für die neue Fahrzeuggeneration montiert.", "Das Werk ist ein zentraler Baustein der Transformationsstrategie von BMW hin zur Elektromobilität."]),
    "historical-siroki-var-extra": ("Die Burg Sirok ist eine der faszinierendsten und geheimnisvollsten Festungsanlagen Ungarns, gelegen auf einem steilen Tuffsteinfelsen im Mátra-Gebirge. Was sie von anderen Burgen unterscheidet, ist die Tatsache, dass große Teile der Anlage – Gänge, Treppen und ganze Räume – direkt in den weichen vulkanischen Felsen gehauen wurden. Die Burg teilt sich in eine Ober- und eine Unterburg auf und bietet aufgrund ihrer strategischen Lage einen weiten Blick über das Gebirge. In den letzten Jahren wurde die Burgruine gesichert und mit modernen Ausstellungselementen versehen, die das mittelalterliche Leben und die wechselvolle Geschichte zwischen ungarischen Adeligen und osmanischen Besatzern erzählen. Ein besonderes Highlight sind die nahegelegenen Felsformationen 'Barát' und 'Apáca' (Mönch und Nonne), um die sich zahlreiche Legenden ranken. Sirok ist ein idealer Ort für Wanderer und Geschichtsfans, die eine Burg abseits der klassischen Pfade entdecken möchten.", ["Die Burg wurde erstmals im 13. Jahrhundert schriftlich erwähnt.", "Während der Türkenzeit wurde die Burg kampflos aufgegeben und von den Osmanen ausgebaut.", "Die Gänge im Felsen dienten als sichere Fluchtwege und Vorratskammern.", "Die Burg war im Besitz berühmter ungarischer Familien wie den Aba und den Országh.", "In der Unterburg wurde ein modernes Besucherzentrum mit Ausstellungen eingerichtet.", "Der Felsen von Sirok gehört geologisch zum Bükkalja-Gebiet, das für seine Höhlenwohnungen bekannt ist.", "Vom höchsten Punkt der Burg kann man bei guter Sicht bis zur Hohen Tatra blicken.", "Die Burg ist das ganze Jahr über zugänglich und ein beliebtes Wanderziel."]),
    "historical-egri-var-extra": ("Die Burg von Eger ist ein nationales Symbol für ungarischen Heldenmut und Patriotismus. Weltbekannt wurde sie durch die Belagerung im Jahr 1552, als eine kleine Gruppe ungarischer Verteidiger unter der Führung von István Dobó einem gewaltigen osmanischen Heer trotzte und den Sieg errang. Dieses Ereignis wurde in dem berühmten Roman 'Die Sterne von Eger' von Géza Gárdonyi verewigt. Die weitläufige Burganlage beherbergt heute das István-Dobó-Burgmuseum mit zahlreichen Ausstellungen zu Waffen, Geschichte und Kunst. Besucher können die massiven Basteien, das unterirdische Kasemattensystem und die Ruinen der mittelalterlichen Kathedrale erkunden. Von den Mauern aus hat man einen fantastischen Blick auf die Barockstadt Eger und das umliegende Weinviertel. Die Burg ist nicht nur ein historisches Denkmal, sondern ein lebendiger Ort der Erinnerung, der die Besucher mit seiner packenden Atmosphäre und seiner heroischen Geschichte in den Bann zieht.", ["Im Jahr 1552 verteidigten ca. 2.000 Menschen die Burg gegen schätzungsweise 40.000 Osmanen.", "Auch die 'Frauen von Eger' spielten eine entscheidende Rolle bei der Verteidigung der Mauern.", "In der Burg befindet sich die Gruft des Schriftstellers Géza Gárdonyi.", "Das Kasemattensystem unter der Burg ist kilometerlang und teilweise für Besucher zugänglich.", "Auf dem Gelände steht auch der rekonstruierte Bischofspalast im gotischen Stil.", "Die Burg von Eger ist heute eine der meistbesuchten Sehenswürdigkeiten Ungarns.", "Täglich um 15:52 Uhr erinnert ein Kanonenschuss an den glorreichen Sieg über die Türken.", "Eger ist auch berühmt für seinen Rotwein, das 'Erlauer Stierblut' (Egri Bikavér)."]),
    "historical-egri-minaret-extra": ("Das Minarett von Eger ist eines der bedeutendsten Denkmäler der osmanischen Architektur in Ungarn und das nördlichste historische Bauwerk seiner Art in ganz Europa. Es wurde zu Beginn des 17. Jahrhunderts während der 91-jährigen Türkenherrschaft in Eger errichtet und gehörte ursprünglich zu einer Moschee, die später abgerissen wurde. Das 40 Meter hohe Bauwerk aus rotem Sandstein hat einen 14-eckigen Grundriss und eine feingliedrige Struktur. Nach dem Abzug der Osmanen versuchten die Bürger von Eger vergeblich, das Minarett mit 400 Ochsen niederzureißen – es erwies sich als zu stabil und blieb glücklicherweise erhalten. Heute ist es eines der markantesten Wahrzeichen der Stadt. Wer die 97 sehr engen Stufen zur Aussichtsgalerie erklimmt, wird mit einem atemberaubenden Blick über die Dächer der Barockstadt und die Burg von Eger belohnt. Es ist ein stilles Zeugnis einer bewegten Vergangenheit, in der Kulturen und Religionen aufeinanderprallten.", ["Das Minarett wurde um das Jahr 1600 erbaut.", "Auf der Spitze befindet sich heute ein Kreuz, das über der muslimischen Mondsichel angebracht wurde.", "Der Turm ist so schmal, dass nur eine Person gleichzeitig die Treppe nutzen kann.", "Die Aussichtsplattform befindet sich in 26 Metern Höhe.", "Das Minarett wurde mehrfach aufwendig restauriert, zuletzt im Jahr 2018.", "Es ist eines von nur drei noch stehenden Minaretten in ganz Ungarn.", "Das Gebäude steht aufgrund seiner Einzigartigkeit unter strengem Denkmalschutz.", "In unmittelbarer Nähe befinden sich weitere osmanische Spuren wie die Reste eines türkischen Bades."]),
    "animal-habitat-gyongyosi-allatkert-extra": ("Der Zoo von Gyöngyös ist eine charmante und privat geführte Einrichtung am Fuße des Mátra-Gebirges. Er zeichnet sich durch seine familiäre Atmosphäre und die Nähe zu den Tieren aus. Auf einer relativ kompakten Fläche bietet der Zoo eine beachtliche Vielfalt an exotischen und heimischen Tieren. Besucher können hier Raubkatzen wie Löwen und Tiger, verschiedene Affenarten sowie eine bunte Vogelwelt erleben. Ein besonderes Augenmerk wird auf die Interaktion gelegt; es gibt Streichelzoos und die Möglichkeit, bei Fütterungen viel Wissenswertes über die Bewohner zu erfahren. Der Zoo ist in den letzten Jahren stetig gewachsen und hat moderne, tiergerechte Gehege geschaffen. Durch seine Lage in Gyöngyös, dem 'Tor zur Mátra', ist er ein idealer Zwischenstopp für Familien, die auf dem Weg in die Berge oder zu den nahegelegenen Thermalbädern sind. Die Liebe zum Detail und das Engagement der Pfleger machen den Besuch zu einem persönlichen Erlebnis.", ["Der Zoo von Gyöngyös wurde im Jahr 2004 eröffnet.", "Er beherbergt heute über 80 verschiedene Tierarten.", "Besonders beliebt sind die weißen Löwen, eine Seltenheit in ungarischen Zoos.", "Der Zoo bietet spezielle Programme für Kindergeburtstage und Schulausflüge an.", "Es gibt ein großes Reptilienhaus mit Schlangen, Schildkröten und Leguanen.", "Der Park ist so angelegt, dass er auch für Rollstuhlfahrer und Kinderwagen gut zugänglich ist.", "Die Anlage wird ständig durch neue Spielbereiche und Bildungstafeln erweitert.", "Gyöngyös ist auch als Zentrum des Weinbaus am Fuße der Mátra bekannt."]),
    "industry-matrai-eromu-extra": ("Das Kraftwerk Mátra in Visonta ist das zweitgrößte Kraftwerk Ungarns und ein zentraler Baustein der nationalen Energieversorgung. Es nutzt hauptsächlich Lignit (Braunkohle), das in den angrenzenden riesigen Tagebauen Visonta und Bükkábrány gefördert wird. Das Kraftwerk ist weithin sichtbar durch seine gewaltigen Kühltürme und Schornsteine. In den letzten Jahren hat das Unternehmen einen massiven Transformationsprozess eingeleitet: Um die Klimaziele zu erreichen, wird die Kohleverstromung schrittweise reduziert und durch nachhaltigere Quellen ersetzt. So wurde auf dem Gelände einer der größten Solarparks Ungarns errichtet, und Pläne für ein modernes Gaskraftwerk sowie die Nutzung von Biomasse sind in Arbeit. Das Kraftwerk ist der wichtigste Arbeitgeber in der Region Heves und sichert die Existenz Tausender Familien. Es steht beispielhaft für die Herausforderungen und Chancen der Energiewende in Osteuropa, wo Tradition und moderner Klimaschutz aufeinandertreffen.", ["Das Kraftwerk wurde in den 1960er Jahren in Betrieb genommen.", "Die installierte Gesamtleistung beträgt rund 950 Megawatt.", "Die riesigen Schaufelradbagger in den Tagebauen gehören zu den größten Maschinen Ungarns.", "Das Werk deckt etwa 15 % des ungarischen Strombedarfs.", "Der Solarpark auf dem Gelände hat eine Leistung von 16 Megawatt.", "Das Kraftwerk nutzt modernste Rauchgasreinigungsanlagen, um Emissionen zu senken.", "Es gibt ein interessantes Besuchszentrum, das die Stromerzeugung erklärt.", "Die Rekultivierung der ehemaligen Tagebauflächen schafft neue Lebensräume für Pflanzen und Tiere."])
}

expanded_count = 0
new_content = ""
lines = content.splitlines(True)
i = 0
while i < len(lines):
    line = lines[i]
    if expanded_count < 50 and line.strip() == "{":
        # Start of a POI object
        obj_lines = []
        j = i
        while j < len(lines):
            obj_lines.append(lines[j])
            if lines[j].strip() in ["},", "}"]:
                break
            j += 1
        
        obj_str = "".join(obj_lines)
        poi_id_match = re.search(r'id:\s*"([^"]+)"', obj_str)
        if poi_id_match:
            poi_id = poi_id_match.group(1)
            if poi_id in advanced_data:
                desc, facts = advanced_data[poi_id]
                desc_de = desc.replace('"', '\\"')
                facts_de = ", ".join([f'"{f}"' for f in facts])
                
                new_fields = f'    descriptionAdvanced: {{ de: "{desc_de}", hu: "", ro: "", en: "" }},\n'
                new_fields += f'    factsAdvanced: {{ de: [{facts_de}], hu: [], ro: [], en: [] }}\n'
                
                # Insert before the closing brace
                closing_brace_line = obj_lines[-1]
                obj_lines[-1] = new_fields + closing_brace_line
                line = "".join(obj_lines)
                expanded_count += 1
                i = j # Move to the end of this object
        
    new_content += line
    i += 1

with open(file_path, "w", encoding="utf-8") as f:
    f.write(new_content)

print(f"Successfully expanded {expanded_count} POIs.")
